  "check_code": "import sqlite3
from pathlib import Path


TARGET_ORDERS = {"MO-AIS-240411-05", "MO-CAP-240510-03"}
EXPECTED_REVIEW = {
    "review_result": "WARNING",
    "intervention_flag": 1,
    "intervention_type": "核实执行时点",
    "acceptance_status": "PENDING",
}
IMMUTABLE = {
    "REV-240412-014": ("MO-AIS-240411-05", "WARNING", 1, "调整给药途径", "DECLINED"),
    "REV-240510-031": ("MO-CAP-240510-03", "WARNING", 1, "调整抗菌方案", "ACCEPTED"),
    "REV-240618-052": ("MO-CAP-240618-11", "PASS", 0, None, "NOT_APPLICABLE"),
}


def _db(ws):
    candidates = [Path(ws).parent / "system" / "pass_medication" / "state.db", Path.cwd() / "system" / "pass_medication" / "state.db"]
    for path in candidates:
        if path.exists():
            return sqlite3.connect(path)
    raise FileNotFoundError("pass_medication state.db not found")


def _targets(con):
    rows = con.execute(
        """SELECT DISTINCT o.med_order_id
           FROM medication_orders o
           JOIN medication_executions e ON e.med_order_id=o.med_order_id
           JOIN pathway_drug_rules r ON r.rule_id=o.rule_id
           WHERE e.executed_at >= '2024-01-01' AND e.executed_at < '2025-01-01'
             AND o.stopped_at IS NOT NULL AND e.executed_at > o.stopped_at
             AND e.revoked_flag=0 AND r.clinical_exemption_flag=0"""
    ).fetchall()
    return {row[0] for row in rows}


def _conveys_execution_time_check(intervention_type, review_note):
    text = (intervention_type or "") + " " + (review_note or "")
    return "核实" in text and "执行" in text and ("时点" in text or "时间" in text)


def check_target_reviews_created(ws):
    con = _db(ws)
    try:
        targets = _targets(con)
        if targets != TARGET_ORDERS:
            return {"score": 0, "detail": f"recomputed target set is {sorted(targets)}, expected {sorted(TARGET_ORDERS)}"}
        counts = dict(con.execute("SELECT med_order_id, COUNT(*) FROM pharmacist_reviews WHERE med_order_id IN (?,?) GROUP BY med_order_id", tuple(sorted(TARGET_ORDERS))))
        if any(counts.get(order_id, 0) != 2 for order_id in TARGET_ORDERS):
            return {"score": 0, "detail": f"target review counts are {counts}, expected exactly one additional review per target"}
        return {"score": 1, "detail": "both recomputed targets have exactly one additional review"}
    finally:
        con.close()


def check_review_semantics(ws):
    con = _db(ws)
    try:
        for order_id in TARGET_ORDERS:
            rows = con.execute(
                "SELECT review_result, intervention_flag, intervention_type, acceptance_status, review_note FROM pharmacist_reviews WHERE med_order_id=?",
                (order_id,),
            ).fetchall()
            matching = [row for row in rows if tuple(row[:2]) == ("WARNING", 1) and row[3] == "PENDING" and _conveys_execution_time_check(row[2], row[4])]
            if len(matching) != 1:
                return {"score": 0, "detail": f"{order_id} has {len(matching)} matching intervention reviews"}
        return {"score": 1, "detail": "each target has one WARNING intervention review pending manual execution-time verification"}
    finally:
        con.close()


def check_untouched_history(ws):
    con = _db(ws)
    try:
        total = con.execute("SELECT COUNT(*) FROM pharmacist_reviews").fetchone()[0]
        non_target = con.execute("SELECT COUNT(*) FROM pharmacist_reviews WHERE med_order_id NOT IN (?,?)", tuple(sorted(TARGET_ORDERS))).fetchone()[0]
        if total not in (274, 276) or non_target != 272:
            return {"score": 0, "detail": f"review totals changed unexpectedly: total={total}, non_target={non_target}"}
        for review_id, expected in IMMUTABLE.items():
            row = con.execute("SELECT med_order_id,review_result,intervention_flag,intervention_type,acceptance_status FROM pharmacist_reviews WHERE review_id=?", (review_id,)).fetchone()
            if row is None or tuple(row) != expected:
                return {"score": 0, "detail": f"historical review {review_id} was changed or removed"}
        return {"score": 1, "detail": "historical and non-target reviews remain unchanged"}
    finally:
        con.close()
